arguments.command:
python3 - <<'PY'
import subprocess, sys, json, xml.etree.ElementTree as ET, email.utils, datetime, re
from urllib.parse import urlparse
UA='Mozilla/5.0 (compatible; OpenClawScout/1.0)'
feeds=[
 ('CoinDesk','https://www.coindesk.com/arc/outboundfeeds/rss/'),
 ('CoinTelegraph','https://cointelegraph.com/rss'),
 ('Decrypt','https://decrypt.co/feed'),
 ('Google News','https://news.google.com/rss/search?q=cryptocurrency+OR+blockchain+OR+ethereum+OR+solana+OR+altcoin+OR+%22digital+assets%22+OR+XRP+OR+cardano+-dogecoin+-shiba+-pepe+-floki+-bonk+-wif+-memecoin+-%22meme+coin%22&hl=en-US&gl=US&ceid=US:en'),
 ('BeInCrypto','https://beincrypto.com/feed/'),
 ('The Block','https://www.theblock.co/rss.xml'),
 ('CryptoSlate','https://cryptoslate.com/feed/'),
 ('CryptoFox Markets','https://cryptofox.news/rss/markets/'),
 ('CryptoFox Regulation','https://cryptofox.news/rss/regulation/'),
]
now=datetime.datetime.now(datetime.timezone.utc)
cutoff=now-datetime.timedelta(hours=24)
for name,url in feeds:
    try:
        xml=subprocess.check_output(['curl','-sL','-A',UA,url,'--max-time','12'], text=True)
        status='ok'
        if not xml.strip():
            print(f'## {name} EMPTY')
            continue
        # very lightweight parser
        try:
            root=ET.fromstring(xml)
        except Exception as e:
            print(f'## {name} PARSE_ERROR {e}')
            continue
        items=[]
        # rss and atom support
        for item in root.findall('.//item')[:50]:
            title=(item.findtext('title') or '').strip()
            link=(item.findtext('link') or '').strip()
            pub=(item.findtext('pubDate') or item.findtext('{http://purl.org/dc/elements/1.1/}date') or '').strip()
            desc=(item.findtext('description') or '').strip()
            items.append((title,link,pub,desc))
        if not items:
            ns={'atom':'http://www.w3.org/2005/Atom'}
            for entry in root.findall('.//atom:entry',ns)[:50]:
                title=(entry.findtext('atom:title',default='',namespaces=ns) or '').strip()
                link=''
                l=entry.find('atom:link',ns)
                if l is not None:
                    link=(l.get('href') or '').strip()
                pub=(entry.findtext('atom:updated',default='',namespaces=ns) or entry.findtext('atom:published',default='',namespaces=ns) or '').strip()
                desc=(entry.findtext('atom:summary',default='',namespaces=ns) or '').strip()
                items.append((title,link,pub,desc))
        print(f'## {name}')
        count=0
        for title,link,pub,desc in items:
            dt=None
            if pub:
                try:
                    dt=email.utils.parsedate_to_datetime(pub)
                except Exception:
                    try:
                        dt=datetime.datetime.fromisoformat(pub.replace('Z','+00:00'))
                    except Exception:
                        dt=None
            if dt is not None and dt.tzinfo is None:
                dt=dt.replace(tzinfo=datetime.timezone.utc)
            if dt and dt>=cutoff:
                print(json.dumps({'title':title,'link':link,'pub':dt.astimezone(datetime.timezone.utc).isoformat(),'desc':re.sub(r'<[^>]+>',' ',desc)[:180]},ensure_ascii=False))
                count+=1
                if count>=12:
                    break
        if count==0:
            print('(no items in last 24h among first 50 entries)')
    except subprocess.CalledProcessError as e:
        print(f'## {name} FETCH_ERROR {e}')
PY

